class Solution {
public:
 string abbreviateProduct(int left,int right){
  const long long MOD=100000;long long tail=1;int twos=0,fives=0;
  long double logs=0;
  for(int x=left;x<=right;++x){
   logs+=log10l((long double)x);
   int v=x;while(v%2==0){v/=2;++twos;}while(v%5==0){v/=5;++fives;}
   tail=tail*v%MOD;
  }
  int zeros=min(twos,fives);twos-=zeros;fives-=zeros;
  auto power=[&](long long base,int exp){long long r=1;while(exp){if(exp&1)r=r*base%MOD;base=base*base%MOD;exp>>=1;}return r;};
  tail=tail*power(2,twos)%MOD*power(5,fives)%MOD;
  long double digitsLog=logs-zeros;
  if(digitsLog<10.0L-1e-10L){
   // The nonzero product fits into ten decimal digits.
   unsigned long long exact=1;
   for(int x=left;x<=right;++x){
    int v=x;while(v%2==0)v/=2;while(v%5==0)v/=5;
    exact*=v;
   }
   for(int i=0;i<twos;++i)exact*=2;
   for(int i=0;i<fives;++i)exact*=5;
   return to_string(exact)+"e"+to_string(zeros);
  }
  long double fractional=digitsLog-floorl(digitsLog);
  int first=(int)(powl(10.0L,fractional+4)+1e-9L);
  if(first>=100000)first=99999;
  ostringstream os;os<<first<<"..."<<setw(5)<<setfill('0')<<tail<<"e"<<zeros;
  return os.str();
 }
};
